LOCK TABLES `pedidos` WRITE;
/*!40000 ALTER TABLE `pedidos` DISABLE KEYS */;
INSERT INTO `pedidos` VALUES (1,'Reparación','No reconoce las redes wifi.','Nayibe','Favreau',NULL,NULL,'Media','Completado',11,16,2,'2026-04-07 05:09:32','2026-04-07 05:09:32','2026-05-05 09:38:51',11,303,NULL,'Notebook (S/N: 425800824)','pedido_1775549372_69d4bbbc52e85.pdf','remito_entregado_1777545972_69f332f4b19ee.pdf',NULL,'No aplica','Entregado','2026-04-30 07:46:12',NULL,'Nayibe Favreau',''),(2,'Pedido Insumo','Para utilizar en notebook sylverstone.','Evelyn Aylen','Ramirez Tomasini',NULL,NULL,'Media','Completado',11,1,17,'2026-04-08 07:45:25','2026-04-08 07:45:25','2026-05-05 09:38:51',NULL,NULL,NULL,'Mouse Genius USB DX-110','nota_sol_1775645125_69d631c55b19e.pdf','remito_entregado_1775646342_69d63686c0871.pdf',227,'Retiro','Entregado','2026-04-08 08:05:42','2026-04-11','Catalina Chiappe',''),(3,'Pedido Insumo','Solicita 2 Teclados y 2 Mouse.','Maria Larura','Flehr',NULL,NULL,'Alta','Completado',13,46,3,'2026-04-10 06:23:07','2026-04-10 06:23:07','2026-05-05 09:38:51',NULL,NULL,NULL,'Teclado Genius USB KB-116 | Mouse Genius USB DX-110','nota_sol_1775812987_69d8c17b80f13.pdf','remito_entregado_1775818698_69d8d7ca6b496.pdf',228,'Retiro','Entregado','2026-04-10 07:58:18','2026-04-10','Maria Laura Flehr',''),(5,'Soporte','*Formateo de equipo, instalación Ubuntu 22\r\n*Agregado de tarjeta SD 64GB','Nayibe','Favreau',NULL,NULL,'Media','Completado',12,16,11,'2026-04-24 09:12:15','2026-04-24 09:12:15','2026-05-05 09:38:51',12,313,NULL,'Notebook (S/N: 425800829)','pedido_1777032735_69eb5e1f42d97.pdf','remito_entregado_1777545960_69f332e868a73.pdf',NULL,'No aplica','Entregado','2026-04-30 07:46:00',NULL,'Nayibe Favreau',''),(6,'Reparación','El transformador no cargaba.\r\n* Se chequeo completamente y verificamos que el cable presentaba cortes en varios sectores.\r\n* Se testeó con multímetro y notamos que el cargador no funcionaba.\r\nEl mismo no se remplazará por no contar con repuesto en stock.','Nayibe','Favreau',NULL,NULL,'Media','Completado',12,16,11,'2026-04-24 09:46:17','2026-04-24 09:46:17','2026-09-24 13:28:46',12,8,NULL,'Varios - Cargador Notebook Silverstone','pedido_1777034777_69eb6619479a6.pdf','remito_entregado_1777545949_69f332dd0e248.pdf',NULL,'No aplica','Entregado','2026-04-30 07:45:49',NULL,'Nayibe Favreau',''),(7,'Pedido Insumo','','Lujan','Teruel',NULL,NULL,'Media','Completado',11,1,15,'2026-04-28 07:49:53','2026-04-28 07:49:53','2026-05-05 09:38:51',NULL,NULL,NULL,'WebCam 2k PJT-DCM173 USB','nota_sol_1777373393_69f090d138657.pdf','remito_entregado_1777374871_69f0969720ff6.pdf',250,'Retiro','Entregado','2026-04-28 08:14:31','2026-05-01','Pinchulef Vanesa',''),(8,'Pedido Insumo','','Nayibe','Favreau',NULL,NULL,'Media','Completado',14,16,2,'2026-04-29 10:18:29','2026-04-29 10:18:29','2026-05-21 09:06:57',NULL,NULL,NULL,'WebCam 2k PJT-DCM173 USB | Adaptador Auriculares Noganet Jack 3.5 | Auricular Genius C/Micro HS-200C | Parlante Genius SP-Q160 USB-Plug','nota_sol_1777468709_69f2052544c72.pdf','remito_entregado_1779365217_6a0ef56161bf6.pdf',268,'Envío','Entregado','2026-05-21 09:06:57','2026-05-04','Nayibe Favreau',''),(9,'Reparación','Ingresa Notebook para reparación. El equipo tenía instalado Sist Op. Wind 10 sin espacio en disco. Se hizo backup de toda información, se formateo y se instaló nuevo sistema operativo (Ubuntu 22) quedando con más espacio en disco y todas sus aplicaciones actualizadas. \r\nSe hicieron pruebas rigurosas para verificar su óptimo funcionamiento.','Clara','Houriet',NULL,NULL,'Media','Completado',12,21,11,'2026-04-30 09:52:28','2026-04-30 09:52:28','2026-05-21 09:53:09',12,330,NULL,'Notebook (S/N: 425801080)',NULL,'remito_entregado_1779367989_6a0f0035b97ad.pdf',NULL,'Envío','Entregado','2026-05-21 09:53:09','2026-04-30','Clara Houriet',''),(10,'Reparación','Ingresa notebook con pantalla negra.\r\nPresentaba problema de initranfs. Se corrigió con el comando correspondiente.','Clara','Houriet',NULL,NULL,'Media','Completado',12,21,11,'2026-04-30 09:58:48','2026-04-30 09:58:48','2026-05-