INSERT INTO `tareas_comentarios` VALUES (1,24,13,'Se hablo con Hernan el dia 01 Junio por este tema indicando la importancia de contar con el UPS en el rack.','2026-06-02 04:40:12',1),(2,18,13,'Ya los tengo hechos pero me falta pasarlos en limpio.','2026-06-02 04:41:53',1),(3,26,13,'El celular de Erbin esta en el corportaivo','2026-06-03 05:09:08',1),(4,3,13,'Le dije a Rafa que queria la copia aunque este obsoleta','2026-06-08 05:14:56',0),(5,26,13,'La PC de Los Menucos la acercarn a la direccion el dia Miercoles 10 de Junio de 2026','2026-06-09 05:17:07',1),(6,21,11,'En la carpeta compartida en /INFORMATICA/Test Veloc. Internet 06-26, están las imágenes de los test, también hay un archivo \"Test de Velocidad Sedes  09-06-26.ods\" con la informacion de los relevamientos.','2026-06-09 09:26:20',1),(7,12,13,'Insistir a Orlando por esta tarea.','2026-06-30 07:53:09',1),(8,30,11,'Orlando dijo, que se van a quedar ahí provisionalmente, se van a acomodar los cables con precinto y cinta momentáneamente.','2026-06-30 10:23:03',1),(9,32,11,'Se realizo la instalación del puerto de red en el área de MPE.','2026-07-01 11:25:06',1),(10,34,13,'Mouse\r\nTeclado\r\nPasta termica\r\nfichas rj45\r\ncable utp\r\nauticulares vincha con 1 y 2 fichas\r\nfuentes\r\ncables scanners\r\nparlantes\r\nCargadores Notebook Silverstone.\r\nDiscos SSD?\r\nPilas PC\r\nAlcohol Isopropilico','2026-07-23 08:06:31',1),(11,34,13,'webcam\r\nPen Drives\r\njacks rj45\r\nMemoria RAM\r\nEstabilizadores','2026-07-23 08:09:32',1),(12,34,13,'Discos duros 2tb 4Tb Para NVR','2026-07-24 08:43:28',1),(13,34,11,'Termocontraible / Patchcore 2 mts (o distintas medidas) / Mini Hdmi a Hdmi (para proyector) / Escalera / Mechas de pared / Pegamentos (gotita - poxipol) / Cable UTP interior y exterior / Cinta ailadora','2026-07-24 09:25:02',1),(14,34,11,'Piso canal / Cable canal / Mega canal / Rosetas / Precintos distintos tamaños / Cinta bifaz / Zapatilla/Regleta? Alargue?','2026-07-24 09:32:37',1),(15,34,11,'Antena Wifi USB','2026-07-24 09:40:08',1),(16,37,11,'probar comentario en notificacion para diego','2026-08-04 12:31:46',1),(17,34,12,'Cable USB para impresora - Cutter (Si es metálico mejor)','2026-08-05 08:32:39',1),(18,35,11,'Ya quedo la PC formateada con, windows 10 y Ubuntu 24 (en dominio), falta instalar sistema de camaras.','2026-08-05 11:05:19',1),(19,37,11,'ya revisamos todo con heber y lo dejamos listo para que cargue el chofer.','2026-08-07 13:36:54',1),(20,34,11,'Esquinero o codo de cable canal (uniones)','2026-08-19 10:40:05',1),(21,40,11,'Se retiraron las PC de la Oficina de MPI. Se preparo a espera de configurar los usuarios.','2026-08-21 11:13:55',1),(22,38,11,'Quedo en el armario revisada y lista para cargar usuarios una silverstone.','2026-08-21 11:14:43',1),(23,38,11,'Ya se entrego','2026-09-02 08:46:11',1),(24,33,11,'Se soluciono con conexión wifi.','2026-09-02 08:47:05',1);
